// Pulse — a voice guide that tours each page.
//
// It spotlights one part of the page at a time, explains it out loud using
// the browser's built-in speech synthesis (no network, no API key), highlights
// each word as it is spoken, and reads live numbers from the running system.
// On the control room and race pages it can also drive the demo itself:
// start traffic, break servers, run the race and read out the result.
//
// The narration is scripted, not generated by a language model: the words
// are written below, and the live numbers are filled in at the moment they
// are spoken. Questions typed into the "ask" box are matched against a small
// built-in knowledge base.
"use strict";
(() => {
  const PAGE = document.body.dataset.page || "home";
  const synth = "speechSynthesis" in window ? window.speechSynthesis : null;
  const S = () => window.PULSE_STATE || {};
  const A = () => window.PULSE_ACTIONS || {};
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  // ---------- speaking helpers ----------
  const say = {
    ms(v) {
      if (!v) return "zero milliseconds";
      if (v >= 1000) return `${(v / 1000).toFixed(1)} seconds`;
      return `${Math.round(v)} milliseconds`;
    },
    n(v) { return Math.round(v || 0).toLocaleString("en-IN"); },
    pct(v) { return `${(+v).toFixed(1).replace(/\.0$/, "")} percent`; },
  };
  const point = () => (S().summary || {}).point || {};
  const backend = (name) => (point().backends || []).find((b) => b.name === name) || {};
  const latestEvent = (levels) => {
    const ev = (S().events || []).filter((e) => !levels || levels.includes(e.level));
    return ev.length ? ev[ev.length - 1].msg : "";
  };
  const side = (key) => (S().sides || []).find((x) => x.key === key) || {};
  const sidePct = (key) => {
    const p = ((side(key).summary || {}).point) || {};
    const done = (p.ok || 0) + (p.errors || 0) + (p.shed || 0);
    return done ? (100 * p.ok) / done : 100;
  };

  // ---------- tours ----------
  const TOURS = {
    home: [
      { sel: "#hero h1", title: "Hi, I'm Pulse", say: "Hi! I'm Pulse, your guide. This is PulseLB, a load balancer built from scratch in Go. In the next two minutes I'll show you what it does and why it's different." },
      { sel: "#problem", title: "The problem", say: "Picture ten A.M. Tatkal booking opens, and lakhs of people press Book in the same second. A load balancer spreads that traffic over many servers. The hard part is what happens when one server gets slow, or crashes, right in the middle of the rush." },
      { sel: "#flow", title: "How a request flows", say: "Every request goes through six steps. It's classified by priority. It's admitted, or quickly and politely refused. It's sent to the faster of two servers. The response time is learned. And if a read fails, it's retried on a different server." },
      { sel: "#features", title: "Self-healing", say: "These are the self-healing features. Smart routing measures every server's live speed. Broken servers are ejected in milliseconds. Recovered servers warm up slowly. Retries have a budget. When traffic outruns capacity, browsing is turned away first, so bookings stay fast. And the autoscaler launches new servers by itself." },
      { sel: "#results", title: "The proof", say: "Here's the proof. Two independent tools measured ten thousand requests per second. In the head to head race, classic round robin completed about seventy seven percent of bookings. PulseLB completed ninety nine point eight percent, with zero failed requests." },
      { sel: "#demo", title: "Your turn", say: "Now it's your turn. Open the control room to break servers yourself, or race mode to watch both balancers fight the same rush. I'll be there too. Just press the voice guide button." },
    ],

    dashboard: [
      { sel: ".brand", title: "The control room", say: "Welcome to the control room. Everything here is live. I'll drive this demo myself, so just watch. You can pause or skip me at any time." },
      { sel: "#trafficCard", title: "Traffic on", before: () => A().traffic && A().traffic(5000, "tatkal"),
        say: "First, I'm switching on five thousand requests per second, using the Tatkal mix: twenty percent bookings, fifty percent searches and thirty percent browsing.", wait: 3500 },
      { sel: "#nowBanner", title: "Right now", say: () => {
        const m = (document.getElementById("nowMsg") || {}).textContent || "";
        return `This line sums up the whole page in plain English, every second. Right now it says: ${m}`;
      } },
      { sel: "#tiles", title: "Live numbers", say: () => {
        const p = point();
        const done = (p.ok || 0) + (p.errors || 0) + (p.shed || 0);
        return `Right now PulseLB is serving ${say.n(p.ok)} requests per second, with ${say.pct(done ? 100 * p.ok / done : 100)} success. Even the slowest one percent of requests finish within ${say.ms(p.p99)}.`;
      } },
      { sel: "#thrCard", title: "Throughput", say: "This chart shows every second of traffic. Blue is served, amber is politely shed, red is errors. You want to see a solid block of blue." },
      { sel: "#latCard", title: "Latency", say: "This one shows response time. The dashed line is the target of two hundred and fifty milliseconds. If latency crosses it, PulseLB starts protecting bookings." },
      { sel: "#backends", title: "Three servers", say: "These are the three servers. The blue bar is each server's share of traffic. While they're equally fast, smart routing keeps them roughly equal." },
      { sel: '[data-be="backend-2"]', title: "Breaking backend-2", before: () => A().chaos && A().chaos("backend-2", "delay=300"),
        say: "Now I'm breaking backend two. Every request it handles takes three hundred extra milliseconds, but it still passes health checks. A normal load balancer would never notice.", wait: 5000 },
      { sel: '[data-be="backend-2"]', title: "Routed around", say: () => {
        const b = backend("backend-2");
        return `Look at backend two now. Its share of traffic has dropped to ${say.pct((b.share || 0) * 100)}. PulseLB measured it at ${say.ms(b.ewma)} and moved the work to the fast servers. Nobody touched anything.`;
      } },
      { sel: "#journalCard", title: "Decision journal", say: () => {
        const m = latestEvent(["warn", "crit"]);
        return "This is the decision journal. It explains every decision in plain English." + (m ? ` The latest one says: ${m}` : "");
      } },
      { sel: '[data-be="backend-3"]', title: "Crashing backend-3", before: () => A().chaos && A().chaos("backend-3", "crash=25"),
        say: "Now something worse. I've just crashed backend three completely. Watch what happens.", wait: 6000 },
      { sel: "#serversSection", title: "Self-healing", say: () => {
        const bs = point().backends || [];
        const up = bs.filter((b) => b.state === "healthy" || b.state === "warming").length;
        const auto = bs.filter((b) => b.managed).length;
        return `PulseLB ejected backend three after five failed requests, retried those reads on healthy servers, and the autoscaler stepped in. There are now ${up} healthy servers, ${auto ? `including ${auto} that PulseLB launched on its own` : "and a replacement on the way"}.`;
      } },
      { sel: "#lanesCard", title: "Priority lanes", say: "These lanes show the three priorities. If traffic ever outruns capacity, browsing is turned away first, then search. Bookings and payments keep flowing until the very end." },
      { sel: "#featuresCard", title: "Feature switches", say: "Every self-healing feature can be switched off live. Try it later: turn them off, break a server, and watch how much an ordinary load balancer suffers." },
      { sel: "#algo", title: "Your turn", before: async () => {
        if (A().chaos) { await A().chaos("backend-2", "reset=true").catch(() => {}); }
        if (A().traffic) await A().traffic(1000, "tatkal");
      }, say: "I've repaired backend two and turned traffic down. You can switch the routing algorithm here, to round robin for example, and compare. When you're ready, open race mode for the head to head battle." },
    ],

    arena: [
      { sel: ".brand", title: "Race mode", say: "This is race mode. Two identical worlds, each with three servers. On the left, a classic round robin load balancer. On the right, PulseLB. They get the same traffic and the same failures, at exactly the same moment." },
      { sel: "#sides", title: "Two sides", say: "Each side has its own live numbers, chart, server shares and journal. Orange is classic, blue is PulseLB." },
      { sel: "#scenarioCard", title: "The race", run: commentary },
      { sel: "#compare", title: "Head to head", say: "These two charts compare both sides second by second. Every spike in the orange line is users waiting, or failing. That's PulseLB. Thanks for watching!" },
    ],
  };

  // Live sports-style commentary while the race runs.
  async function commentary(tok) {
    const lines = {
      0: [{ sel: "#scenarioCard", say: "And they're off! It's nine fifty nine, normal morning traffic. Both balancers look identical." }],
      1: [{ sel: "#scenarioCard", say: "Ten A.M.! Tatkal booking opens and traffic triples, to seventy five percent of capacity." }],
      2: [
        { sel: "#side-classic", say: "Backend two has slowed down by four hundred milliseconds. Watch the classic side. Round robin keeps feeding it a third of all traffic." },
        { sel: "#sides", delay: 3500, say: () => `Classic success is down to ${say.pct(sidePct("classic"))}. PulseLB is holding ${say.pct(sidePct("pulse"))}.` },
      ],
      3: [
        { sel: "#side-pulse", say: "Backend three just crashed! The classic side waits for health checks. PulseLB ejects it instantly and launches a replacement." },
        { sel: "#sides", delay: 3500, say: () => `Right now: classic at ${say.pct(sidePct("classic"))}, PulseLB at ${say.pct(sidePct("pulse"))}.` },
      ],
      4: [{ sel: "#scenarioCard", say: "Backend two is repaired." }],
      5: [{ sel: "#scenarioCard", say: "The rush is over. Traffic is back to normal." }],
      6: [{ sel: "#scenarioCard", say: "Final whistle! Let's wait for the last requests and look at the scoreboard." }],
    };
    if (A().startRace) await A().startRace();
    await speak("Let's start the race. I'll commentate.", tok);
    // Wait for the stream to report the new race, so a finished earlier
    // race isn't mistaken for this one.
    for (let i = 0; i < 40 && !((S().scen || {}).running); i++) await sleep(250);
    let last = -1;
    for (;;) {
      if (tok !== G.tok) return;
      const v = S().scen || {};
      if (v.finished && last >= 6) break;
      if (v.running && v.stage > last) {
        last = v.stage;
        for (const ln of lines[last] || []) {
          if (ln.delay) await sleep(ln.delay);
          if (tok !== G.tok) return;
          spot(ln.sel, G.steps[G.i].title);
          await speak(typeof ln.say === "function" ? ln.say() : ln.say, tok);
        }
        continue;
      }
      if (v.finished) break;
      await sleep(300);
    }
    // Wait for the frozen scoreboard, then read the verdict.
    for (let i = 0; i < 40 && !((S().scen || {}).finished); i++) await sleep(250);
    const sc = (S().scen || {}).score || [];
    spot("#scoreCard", "Scoreboard");
    if (sc.length === 2) {
      const [c, p] = sc;
      await speak(`Here's the result. Classic round robin completed ${say.pct(c.booking_pct)} of Tatkal bookings. PulseLB completed ${say.pct(p.booking_pct)}. Classic had ${say.n(c.errors)} failed requests. PulseLB had ${say.n(p.errors)}. And the slowest one percent of PulseLB's requests took ${say.ms(p.p99)}, against ${say.ms(c.p99)} for classic.`, tok);
    } else {
      await speak("The race is over. The scoreboard is above.", tok);
    }
  }

  // ---------- questions ----------
  const KB = [
    { k: ["what is", "pulselb", "about", "project", "explain", "overview"], sel: null,
      a: "PulseLB is a load balancer written from scratch in Go, with no external libraries. It spreads traffic over many servers, routes around slow ones, heals itself when one dies, protects important requests under overload, and explains every decision." },
    { k: ["load balancer", "what does a load balancer", "why need"], sel: null,
      a: "A load balancer sits in front of many servers and decides which one handles each request, so no single server is overwhelmed and the site stays up even when a server fails." },
    { k: ["p2c", "ewma", "algorithm", "routing", "choose", "pick", "smart"], sel: "#algo",
      a: "For every request I pick two random healthy servers and send the request to the one with the lower cost. Cost is the server's recent average response time multiplied by how many requests it's already handling. Comparing only two stops everyone stampeding onto one server. Linkerd and Twitter's Finagle use the same idea." },
    { k: ["round robin", "classic", "difference", "different", "unique", "special"], sel: null,
      a: "Round robin just takes turns. It can't tell that a server is slow if that server still passes health checks, so it keeps sending it a third of the traffic. PulseLB measures every response and moves traffic away within a second." },
    { k: ["10k", "10,000", "ten thousand", "rps", "throughput", "benchmark", "measured", "fast"], sel: "#results",
      a: "Two independent tools measured it on one laptop. Our own generator, blast, saw nine thousand nine hundred and ninety seven requests per second at ninety nine point nine seven percent success. Grafana k6 saw nine thousand nine hundred and ninety three per second with zero failures." },
    { k: ["shed", "503", "priority", "overload", "turned away", "browse", "booking"], sel: "#lanesCard",
      a: "When latency crosses the two hundred and fifty millisecond target, I lower my concurrency limit. Browsing is turned away first, above half the limit. Search goes next, above eighty percent. Bookings and payments may use the whole limit. The refused requests get a fast 503 with a retry-after header, instead of a slow timeout." },
    { k: ["eject", "ejection", "crash", "dead", "fail", "health"], sel: "#serversSection",
      a: "Health checks run every second, but they take a couple of seconds to notice a problem. So I also watch real traffic. If five requests in a row fail, the server is ejected for five seconds, then ten, then twenty. I never eject more than half the fleet." },
    { k: ["slow start", "warm", "recover"], sel: null,
      a: "When a server comes back, it starts with ten percent of its normal share and ramps up over eight seconds. A cold server flooded with traffic often falls over again straight away." },
    { k: ["retry", "retries", "budget", "storm"], sel: null,
      a: "Failed reads are retried on a different server. But retries are capped at about twenty percent extra load, with a floor of ten per second, so one sick server can't cause a retry storm that takes down the healthy ones." },
    { k: ["autoscale", "scale", "new server", "auto-"], sel: null,
      a: "I keep a target number of healthy servers. If one dies, I launch a replacement within about three seconds. If the fleet is overloaded for three seconds, I raise the target. When traffic drops, extra servers are drained and retired." },
    { k: ["journal", "explain", "why"], sel: "#journalCard",
      a: "The decision journal is my diary. Every time I eject a server, shed traffic, scale or reroute, I write down what I did and why, in plain English." },
    { k: ["race", "arena", "fair", "scoreboard"], sel: null,
      a: "Race mode builds two identical worlds with three servers each. Same traffic, same failures, same moment. The scoreboard is measured by the traffic generator, so it's what users would have experienced." },
    { k: ["go", "language", "built", "tech", "stack", "dependencies"], sel: null,
      a: "It's written in Go using only the standard library. The proxy, the routing, the histogram, the load generator and even these charts are written from scratch." },
    { k: ["are you ai", "who are you", "ai", "bot", "pulse"], sel: null,
      a: "I'm Pulse, PulseLB's guide. To be honest, I'm not a large language model. My explanations are written in advance and I fill in the live numbers as I speak. I run entirely in your browser, with no internet needed." },
  ];
  const CHIPS = ["How does routing work?", "Why shed traffic?", "How was 10k measured?", "What's different from round robin?", "Are you an AI?"];

  function answer(q) {
    const s = q.toLowerCase();
    let best = null, score = 0;
    for (const e of KB) {
      const sc = e.k.reduce((n, k) => n + (s.includes(k) ? k.length : 0), 0);
      if (sc > score) { best = e; score = sc; }
    }
    return best || { a: "I don't know that one yet. Try asking about routing, shedding, ejection, retries, autoscaling, the race, or how ten thousand requests per second was measured.", sel: null };
  }

  // ---------- UI ----------
  const ORB = `<span class="orb" aria-hidden="true"><span class="face">
      <span class="eyes"><i></i><i></i></span>
      <span class="mouth"><i></i><i></i><i></i><i></i><i></i></span>
    </span></span>`;
  const WAVE = Array.from({ length: 9 }, () => "<i></i>").join("");

  const G = { steps: [], i: -1, playing: false, tok: 0, muted: false, open: false };
  let bot, panel, spotEl, hello, titleEl, textEl, countEl, playBtn, muteBtn, progEl, curTarget = null;

  function build() {
    bot = el("button", { id: "pg-bot", "aria-label": "Open Pulse, the voice guide", title: "Pulse — voice guide" });
    bot.innerHTML = ORB;
    bot.addEventListener("click", () => (G.open ? closePanel() : openPanel(true)));

    spotEl = el("div", { id: "pg-spot" }, el("div", { class: "pg-label" }));
    hello = el("div", { id: "pg-hello", role: "dialog", "aria-label": "Pulse says hello" },
      el("b", {}, "Hi, I'm Pulse 👋"),
      PAGE === "home" ? "Want a 2-minute tour of PulseLB, with voice?" :
      PAGE === "dashboard" ? "Want me to run a live demo here? I'll break servers and explain what happens." :
      "Want me to start the race and commentate it live?",
      el("div", { class: "row" },
        el("button", { class: "primary", onclick: () => { hideHello(); start(); } }, "▶ Yes, start"),
        el("button", { onclick: hideHello }, "Not now")));

    titleEl = el("div", { class: "pg-title" }, "Pulse");
    textEl = el("div", { class: "pg-text", "aria-live": "polite" });
    countEl = el("span", { class: "pg-count num" }, "–");
    playBtn = el("button", { class: "pg-play primary", onclick: togglePlay, "aria-label": "Play or pause" }, "▶ Play");
    muteBtn = el("button", { onclick: toggleMute, "aria-label": "Mute voice" }, "🔊");
    progEl = el("div");
    const waveEl = el("span", { class: "pg-wave", "aria-hidden": "true" });
    waveEl.innerHTML = WAVE;
    const input = el("input", { type: "text", placeholder: "Ask me anything about PulseLB…", "aria-label": "Ask Pulse a question" });
    const form = el("form", { onsubmit: (e) => { e.preventDefault(); if (input.value.trim()) { ask(input.value.trim()); input.value = ""; } } },
      input, el("button", { type: "submit", class: "primary" }, "Ask"));
    panel = el("div", { id: "pg-panel", role: "dialog", "aria-label": "Pulse voice guide" },
      el("div", { class: "pg-head" },
        el("div", { class: "pg-who" }, el("span", { class: "pg-mini" }), el("span", {}, "Pulse", el("small", {}, "AI voice guide"))),
        waveEl,
        el("button", { class: "pg-x", onclick: closePanel, "aria-label": "Close guide" }, "✕")),
      el("div", { class: "pg-body" }, titleEl, textEl),
      el("div", { class: "pg-progress" }, progEl),
      el("div", { class: "pg-ctrl" },
        el("button", { onclick: prev, "aria-label": "Previous step" }, "◀"),
        playBtn,
        el("button", { onclick: next, "aria-label": "Next step" }, "▶▶"),
        muteBtn, countEl),
      el("div", { class: "pg-ask" }, form,
        el("div", { class: "pg-chips" }, ...CHIPS.map((c) => el("button", { type: "button", onclick: () => ask(c) }, c)))));

    document.body.append(spotEl, panel, hello, bot);
    document.querySelectorAll("[data-guide-start]").forEach((b) => b.addEventListener("click", (e) => { e.preventDefault(); hideHello(); start(); }));
    document.addEventListener("keydown", (e) => {
      if (!G.open || e.target.tagName === "INPUT") return;
      if (e.key === "Escape") closePanel();
      else if (e.key === "ArrowRight") next();
      else if (e.key === "ArrowLeft") prev();
    });
    addEventListener("resize", place);
    addEventListener("scroll", place, { passive: true });
    (function frame() { place(); requestAnimationFrame(frame); })();

    setText("Press ▶ Play and I'll walk you through this page out loud. Or ask me a question below.");
    const auto = new URLSearchParams(location.search).get("tour");
    setTimeout(() => {
      if (auto) { openPanel(false); setText("Ready when you are. Press ▶ Play to start."); return; }
      if (!G.open && !sessionStorageGet("pg-hello-" + PAGE)) {
        hello.classList.add("open");
        bot.classList.add("hello");
        sessionStorageSet("pg-hello-" + PAGE, "1");
      }
    }, 1200);
  }

  function setTalking(on) { bot.classList.toggle("talking", on); panel.classList.toggle("talking", on); }
  function sessionStorageGet(k) { try { return sessionStorage.getItem(k); } catch { return null; } }
  function sessionStorageSet(k, v) { try { sessionStorage.setItem(k, v); } catch { /* private mode */ } }
  function hideHello() { hello.classList.remove("open"); bot.classList.remove("hello"); }

  function openPanel() { G.open = true; panel.classList.add("open"); hideHello(); }
  function closePanel() { stop(); G.open = false; panel.classList.remove("open"); }

  // ---------- spotlight ----------
  function spot(sel, label) {
    const t = sel ? document.querySelector(sel) : null;
    curTarget = t;
    spotEl.querySelector(".pg-label").textContent = label || "";
    if (!t) { spotEl.classList.remove("on", "pulse"); return; }
    t.scrollIntoView({ behavior: "smooth", block: t.offsetHeight > innerHeight * 0.7 ? "start" : "center" });
    spotEl.classList.add("on", "pulse");
    place();
  }
  function place() {
    if (!curTarget || !spotEl.classList.contains("on")) return;
    const r = curTarget.getBoundingClientRect(), pad = 10;
    spotEl.style.left = r.left - pad + "px";
    spotEl.style.top = r.top - pad + "px";
    spotEl.style.width = r.width + pad * 2 + "px";
    spotEl.style.height = Math.min(r.height + pad * 2, innerHeight * 1.5) + "px";
    spotEl.classList.toggle("below-label", r.top < 110);
  }

  // ---------- speech with word highlighting ----------
  let voice = null;
  function pickVoice() {
    if (!synth) return;
    const score = (v) => (/^en/i.test(v.lang) ? 20 : 0) + (/en-IN/i.test(v.lang) ? 5 : 0) +
      (/natural|neural/i.test(v.name) ? 8 : 0) + (/online/i.test(v.name) ? 2 : 0) + (/google/i.test(v.name) ? 3 : 0);
    voice = synth.getVoices().slice().sort((a, b) => score(b) - score(a))[0] || null;
  }
  if (synth) { pickVoice(); synth.addEventListener?.("voiceschanged", pickVoice); }

  function setText(text) {
    textEl.replaceChildren();
    const words = [];
    let off = 0;
    for (const part of text.split(/(\s+)/)) {
      if (!part) continue;
      if (/^\s+$/.test(part)) { textEl.append(part); off += part.length; continue; }
      const span = el("span", { class: "todo" }, part);
      words.push({ start: off, end: off + part.length, span });
      textEl.append(span);
      off += part.length;
    }
    return words;
  }
  function mark(words, idx) {
    words.forEach((w, j) => { w.span.className = j < idx ? "said" : j === idx ? "now" : "todo"; });
  }

  // speak resolves when the text has been read (or the tour moved on).
  function speak(text, tok) {
    const words = setText(text);
    setTalking(true);
    const done = () => { if (tok === G.tok) { mark(words, words.length); setTalking(false); } };
    // Split into sentences: long utterances get cut off in some browsers.
    const sentences = [];
    const re = /[^.!?]+[.!?]*\s*/g;
    let m;
    while ((m = re.exec(text))) sentences.push({ text: m[0], start: m.index });
    return (async () => {
      for (const s of sentences) {
        if (tok !== G.tok) return;
        await speakSentence(s, words, tok);
      }
      done();
    })();
  }

  function speakSentence(s, words, tok) {
    const first = words.findIndex((w) => w.start >= s.start);
    const last = words.findIndex((w) => w.start >= s.start + s.text.length);
    const sw = words.slice(first, last < 0 ? words.length : last);
    const est = Math.max(900, sw.length * 330);
    // Timer-based highlighting: used when muted, when speech isn't
    // available, or when the voice doesn't report word boundaries.
    const timed = (resolve) => {
      let k = 0;
      const step = est / Math.max(1, sw.length);
      const iv = setInterval(() => {
        if (tok !== G.tok) { clearInterval(iv); resolve(); return; }
        if (k >= sw.length) { clearInterval(iv); resolve(); return; }
        mark(words, first + k++);
      }, step);
    };
    if (G.muted || !synth) return new Promise((r) => timed(r));
    return new Promise((resolve) => {
      const u = new SpeechSynthesisUtterance(s.text.trim());
      if (voice) { u.voice = voice; u.lang = voice.lang; }
      u.rate = 1.03;
      let gotBoundary = false, finished = false, fallback = null;
      const t0 = performance.now();
      const end = () => {
        if (finished) return;
        finished = true;
        clearTimeout(guard); clearTimeout(fb); clearInterval(fallback);
        // A voice that "finishes" far faster than a person could read the
        // sentence didn't really speak (no voice installed, blocked audio):
        // keep reading pace with the timed highlighter instead.
        if (!gotBoundary && performance.now() - t0 < est * 0.3) timed(resolve);
        else resolve();
      };
      u.onboundary = (e) => {
        if (e.name && e.name !== "word") return;
        gotBoundary = true;
        const abs = s.start + e.charIndex;
        const j = words.findIndex((w) => abs >= w.start && abs < w.end + 1);
        if (j >= 0) mark(words, j);
      };
      u.onend = end;
      u.onerror = end;
      // Some voices never report boundaries: fall back to timing.
      const fb = setTimeout(() => {
        if (gotBoundary || finished) return;
        let k = 0;
        fallback = setInterval(() => { if (k < sw.length) mark(words, first + k++); }, est / Math.max(1, sw.length));
      }, 600);
      // And some browsers occasionally never fire onend.
      const guard = setTimeout(end, est * 2.2 + 4000);
      synth.speak(u);
    });
  }

  // ---------- tour engine ----------
  function start() {
    openPanel();
    if (synth) synth.cancel();
    G.steps = TOURS[PAGE] || TOURS.home;
    G.i = 0;
    G.playing = true;
    runLoop();
  }
  async function runLoop() {
    const tok = ++G.tok;
    if (synth) synth.cancel();
    playBtn.textContent = "❚❚ Pause";
    while (G.playing && tok === G.tok && G.i < G.steps.length) {
      const st = G.steps[G.i];
      countEl.textContent = `${G.i + 1}/${G.steps.length}`;
      progEl.style.width = (100 * (G.i + 1)) / G.steps.length + "%";
      titleEl.textContent = st.title;
      spot(st.sel, st.title);
      try {
        if (st.run) { await st.run(tok); } else {
          if (st.before) { await st.before(); await sleep(400); }
          if (tok !== G.tok) return;
          const text = typeof st.say === "function" ? st.say() : st.say;
          await speak(text, tok);
          if (st.wait && tok === G.tok) await sleep(st.wait);
        }
      } catch (err) {
        console.warn("guide step failed", err);
      }
      if (tok !== G.tok) return;
      await sleep(450);
      if (tok !== G.tok) return;
      G.i++;
    }
    if (tok === G.tok && G.i >= G.steps.length) finish();
  }
  function finish() {
    G.playing = false;
    playBtn.textContent = "↻ Again";
    spot(null);
    titleEl.textContent = "That's the tour";
    const nextPage = PAGE === "home" ? ["Continue in the control room →", "dashboard.html?tour=1"] :
      PAGE === "dashboard" ? ["Continue in race mode →", "arena.html?tour=1"] : ["Back to the start →", "index.html"];
    setText("Ask me anything below, or carry on to the next part of the demo.");
    textEl.append(el("div", { class: "pg-actions" }, el("a", { class: "btn primary", href: nextPage[1] }, nextPage[0])));
    setTalking(false);
    G.i = 0;
  }
  function stop() {
    G.playing = false;
    G.tok++;
    if (synth) synth.cancel();
    setTalking(false);
    playBtn.textContent = "▶ Play";
    spot(null);
  }
  function togglePlay() {
    if (G.playing) { stop(); playBtn.textContent = "▶ Resume"; return; }
    if (!G.steps.length) { start(); return; }
    G.playing = true;
    runLoop();
  }
  function next() { if (!G.steps.length) return start(); G.i = Math.min(G.i + 1, G.steps.length - 1); G.playing = true; runLoop(); }
  function prev() { if (!G.steps.length) return start(); G.i = Math.max(G.i - 1, 0); G.playing = true; runLoop(); }
  function toggleMute() {
    G.muted = !G.muted;
    muteBtn.textContent = G.muted ? "🔇" : "🔊";
    if (G.muted && synth) synth.cancel();
  }
  async function ask(q) {
    openPanel();
    const wasPlaying = G.playing;
    stop();
    if (wasPlaying) playBtn.textContent = "▶ Resume";
    const a = answer(q);
    titleEl.textContent = q.length > 60 ? q.slice(0, 57) + "…" : q;
    const sel = a.sel && document.querySelector(a.sel) ? a.sel : null;
    spot(sel, sel ? "Here" : "");
    const tok = ++G.tok;
    await speak(a.a, tok);
  }

  build();
})();
